const mediaControl=createMediaControl(scope);mediaControl.subscribe(state=>{mediaPaused=state.paused;mediaEpoch=state.generation;if(state.paused||state.phase==='selective-clearing'){for(const controller of downloadJobs.values())controller.abort();verifiedResources.clear();}});
