 if(cached){try{valid=await verifyCached(cached,ref,request.url);}catch{try{await cache.delete(request.url);await broadcast({type:'SAVED_INVENTORY_CHANGED'});}catch{}}}
 if(valid)return isMedia?mediaControl.guard(ticket,()=>valid):valid;
 if(isMedia){const data=await catalog();if(!hostedMediaPaths(data).has(ref.url)){if(allowMediaNetwork)throw new Error('本站不再提供这组下载，请下载资源包后导入');return new Response('Hosted media retired; import a resource package to read locally',{status:404});}}
 if(isMedia&&!allowMediaNetwork&&!await mediaControl.automaticAllowed(request.url))return new Response('Automatic media saving disabled for cleared resources',{status:404});
 if(isMedia&&!allowMediaNetwork){const data=await catalog();const automatic=data.entries.some((entry,index)=>(entry.displayOrdinal??index+1)<=50&&pairRefs(entry,data).some(item=>resolve('gre-learning/'+item.url)===request.url));if(!automatic)return new Response('Download optional media from settings first',{status:404});}
 const network=new AbortController(),abort=()=>network.abort();signal?.addEventListener('abort',abort,{once:true});if(signal?.aborted)abort();const timer=setTimeout(abort,30000);let response;try{response=await fetch(request,{signal:network.signal});if(isMedia&&[404,410].includes(response.status))throw Object.assign(new Error('资源暂不可用'),{code:'MEDIA_UNAVAILABLE'});await verify(response,ref);}finally{clearTimeout(timer);signal?.removeEventListener('abort',abort);}
 if(signal?.aborted)throw new DOMException('Cancelled','AbortError');
 const commit=async()=>{if(signal?.aborted)throw new DOMException('Cancelled','AbortError');if(allowMediaNetwork&&!cache)throw new Error('无法保存到本机，请检查存储空间');if(cache){try{await cache.put(request.url,response.clone());verifiedResources.set(request.url+'|'+ref.sha256+'|'+ref.bytes,Promise.resolve());}catch(error){if(allowMediaNetwork)throw new Error('本机保存失败，请释放存储空间后重试');}}return response;};
 return isMedia?mediaControl.guard(ticket,commit):commit();
